// DualPasswordOption is the AST type name for dual-password actions attached to
// a user spec. It is an alias because the grammar currently builds the same
// option payload shape as PasswordOrLockOption, but only RetainCurrentPassword
// and DiscardOldPassword are valid for this semantic slot.
type DualPasswordOption = PasswordOrLockOption

